abilities = [
    {"id": 1, "name": "Soul Perception", "category": "Soul Ability", "users": [["Death the Kid"], ["Franken Stein"], ["Sid Barrett"], ["Maka Albarn"], ["Akane Hoshi"], ["Feodor"], ["Ox Ford"]], "description": "A special sensory ability that allows the user to perceive souls, soul wavelengths, madness, personalities, emotional states, and combat potential. While primarily possessed by skilled meisters, Demon Weapons can temporarily access Soul Perception through Soul Resonance with their meister.", "continuity": "Manga and Anime", "image_url": "/abilities/soul-perception.png"},
    {"id": 2, "name": "Super Soul Perception", "category": "Sensory Ability", "users": [["Joe Buttataki"]], "description": "An advanced form of Soul Perception that allows Joe Buttataki to sense souls across an exceptionally large area and distinguish subtle wavelength characteristics.", "continuity": "Manga", "image_url": "/abilities/super-soul-perception.png"},
    {"id": 3, "name": "Soul Resonance", "category": "Soul Ability", "users": [["Meister", "Demon Weapon"]], "description": "A fundamental technique performed by a meister and their Demon Weapon in which both synchronize their soul wavelengths, dramatically amplifying their power. Soul Resonance strengthens attacks, enhances existing abilities, enables advanced techniques, and allows partners to communicate through their souls.", "continuity": "Manga and Anime", "image_url": "/abilities/soul-resonance.png"},
    {"id": 4, "name": "Chain Resonance", "category": "Soul Resonance", "users": [["DWMA Meisters", "DWMA Demon Weapons"]], "description": "A coordinated resonance technique that connects the soul wavelengths of multiple meister and weapon teams so they can operate together more effectively.", "continuity": "Manga and Anime"},
    {"id": 5, "name": "Soul Menace", "category": "Soul Ability", "users": [["Franken Stein"], ["Black☆Star"], ["House Hoshi"], ["Akane Hoshi"]], "description": "An advanced meister technique in which the user channels their own soul wavelength directly into an opponent through physical contact. The resulting electrical-like burst produces powerful concussive force and can damage both living targets and Demon Weapons in weapon form.", "continuity": "Manga and Anime", "image_url": "/abilities/soul-menace.png"},
    {"id": 6, "name": "Consecutive Soul Menace Three-Fold", "category": "Soul Ability", "users": [["Franken Stein"]], "description": "An advanced Soul Menace technique in which Stein delivers three consecutive wavelength attacks against the same opponent.", "continuity": "Manga and Anime", "image_url": "/abilities/consecutive-soul-menace-three-fold.png"},
    {"id": 7, "name": "Anti-Demon Wavelength", "category": "Soul Ability", "users": [["Maka Albarn"], ["Tsar Pushka"], ["Feodor"], ["Soul Evans"], ["Tsumigi Harudori"]], "description": "A rare purifying wavelength that is especially effective against magic, madness, Black Blood and other malevolent supernatural forces.", "continuity": "Manga and Anime", "image_url": "/abilities/anti-demon-wavelength.png"},
    {"id": 8, "name": "Anti-Demon Wavelength: Full Force", "category": "Soul Ability", "users": [["Feodor", "Tsar Pushka"]], "description": "A powerful release of Feodor's Anti-Demon Wavelength through Tsar Pushka that spreads its purifying influence through the target and surrounding Black Blood.", "continuity": "Manga", "image_url": "/abilities/anti-demon-wavelength-full-force.png"},
    {"id": 9, "name": "Soul Protect", "category": "Magic", "users": [["Medusa Gorgon"], ["Shaula Gorgon"], ["Tabatha Butterfly"], ["Sofia Valk"], ["Kimial Diehl"], ["Maba"], ["Free"], ["Mizune Family"]], "description": "A spell that conceals a witch's soul wavelength and allows them to avoid detection by people using Soul Perception.", "continuity": "Manga and Anime", "image_url": "/abilities/soul-protect.png"},
    {"id": 10, "name": "Soul Possession", "category": "Soul Ability", "users": [["Masamune Nakatsukasa"], ["Tsubaki Nakatsukasa"], ["Medusa Gorgon"]], "description": "A supernatural ability that allows the user to possess another person's soul. In its weapon form, the user can seize control of their meister's body, while magical variants allow possession through sorcery. The technique can generally be countered by advanced wavelength control.", "continuity": "Manga and Anime", "image_url": "/abilities/soul-possession.png"},
    {"id": 11, "name": "Soul Meditation", "category": "Support Ability", "users": [["Soul Eater Evans", "Maka Albarn"]], "description": "A Soul's Piano technique in which Soul transmits Maka Albarn's Anti-Demon Wavelength across a wide area. By spreading the wavelength through sound, the technique protects others from madness and strengthens their resistance against its effects.", "continuity": "Manga", "image_url": "/abilities/soul-meditation.png"},
    {"id": 12, "name": "Soul Thread Sutures", "category": "Support Ability", "users": [["Franken Stein", "Spirit Albarn"]], "description": "An advanced wavelength control technique that allows the user to fire their soul wavelength into a target and manipulate it like thread, stitching together wounds or binding damaged tissue. The technique can also be applied to the user themselves, but requires exceptional wavelength control.", "continuity": "Manga and Anime", "image_url": "/abilities/soul-thread-sutures.png"},
    {"id": 13, "name": "Soul Threads: Diffuse Sutures", "category": "Support Ability", "users": [["Franken Stein", "Spirit Albarn"]], "description": "An advanced variation of Soul Thread Sutures that manipulates a target's soul wavelength to suture and control their nervous system, temporarily immobilizing their body. The technique requires exceptional precision and can fail against opponents whose soul wavelength is too powerful to control.", "continuity": "Manga and Anime", "image_url": "/abilities/soul-thread-diffuse-sutures.png"},
    {"id": 14, "name": "Witch Hunter", "category": "Soul Resonance", "users": [["Maka Albarn", "Soul Eater Evans"], ["Franken Stein", "Spirit Albarn"]], "description": "A scythe-based Soul Resonance technique that enlarges and reshapes the blade to increase its cutting power, particularly against witches.", "continuity": "Manga and Anime", "image_url": "/abilities/witch-hunter.png"},
    {"id": 15, "name": "Genie Hunter", "category": "Soul Resonance", "users": [["Maka Albarn", "Soul Eater Evans"]], "description": "An advanced form of Witch Hunter strengthened by Maka's Anti-Demon Wavelength, producing a larger and more powerful scythe blade.", "continuity": "Anime", "image_url": "/abilities/genie-hunter.png"},
    {"id": 16, "name": "Demon Hunt", "category": "Soul Resonance", "users": [["Maka Albarn", "Soul Eater Evans"]], "description": "An advanced scythe resonance attack developed beyond Witch Hunter and used against powerful supernatural enemies.", "continuity": "Manga", "image_url": "/abilities/demon-hunt.png"},
    {"id": 17, "name": "Kishin-Hunt", "category": "Soul Resonance", "users": [["Maka Albarn", "Soul Eater Evans"]], "description": "A Soul Resonance technique performed by Maka Albarn and Soul Eater Evans while controlling the Black Blood. By channeling the Black Blood Armor, the pair unleash a powerful slash that completely pierces the target, striking internally and inflicting severe damage.", "continuity": "Manga", "image_url": "/abilities/kishin-hunt.png"},
    {"id": 18, "name": "Full-Weapon Transformation", "category": "Weapon Ability", "users": [["Demon Weapon"], ["Mystical Sword"]], "description": "The natural ability of a demon weapon to transform their entire body into a weapon form that can be wielded by a compatible meister.", "continuity": "Manga and Anime", "image_url": "/abilities/full-weapon-transformation.png"},
    {"id": 19, "name": "Just-Made Tadpole Bomb", "category": "Magic", "users": [["Eruka Frog"]], "description": "A variation of Tadpole Bomb in which Eruka Frog rapidly creates a tadpole-shaped explosive with minimal preparation. Although weaker than her standard Tadpole Bomb, the spell can be cast much more quickly, making it useful when immediate attacks are required.", "continuity": "Manga and Anime", "image_url": "/abilities/just-made-tadpole-bomb.png"},
    {"id": 20, "name": "Multi-Form Transformation", "category": "Weapon Ability", "users": [["Tsubaki Nakatsukasa"]], "description": "Tsubaki's inherited ability to transform into several different ninja weapons, including a chain scythe, smoke bomb, shuriken and ninja sword.", "continuity": "Manga and Anime"},
    {"id": 21, "name": "Uncanny Sword Mode", "category": "Weapon Ability", "users": [["Tsubaki Nakatsukasa"], ["Nakatsukasa Clan"], ["Masamune Nakatsukasa"]], "description": "Tsubaki transforms into the Uncanny Sword inherited from Masamune, granting access to shadow-manipulating Soul Resonance techniques.", "continuity": "Manga and Anime", "image_url": "/abilities/uncanny-sword-mode.png"},
    {"id": 22, "name": "Shadow☆Star Form", "category": "Soul Resonance", "users": [["Black☆Star", "Tsubaki Nakatsukasa"]], "description": "A Soul Resonance technique that allows Black☆Star and Tsubaki Nakatsukasa to manipulate shadows and access a series of specialized weapon transformations known as Shadow☆Star Forms. Each form grants unique offensive or defensive properties while drawing power from the meister's shadow.", "continuity": "Manga and Anime", "image_url": "/abilities/shadow-star-form.png"},
    {"id": 23, "name": "Shadow☆Star Zeroth Form: \"Masamune\"", "category": "Soul Resonance", "users": [["Black☆Star", "Tsubaki Nakatsukasa"]], "description": "A Shadow☆Star Form technique in which Tsubaki Nakatsukasa utilizes her Uncanny Sword transformation to convert Black☆Star's shadow into a scarf-like appendage. The shadow can act as an additional limb for attacking, defending, and extending the user's reach while empowering more advanced Shadow☆Star techniques.", "continuity": "Manga", "image_url": "/abilities/shadow-star-zero-form.png"},
    {"id": 24, "name": "Shadow☆Star First Form: \"Chain of Blackness\"", "category": "Soul Resonance", "users": [["Black☆Star", "Tsubaki Nakatsukasa"]], "description": "A Shadow☆Star Form technique in which Tsubaki Nakatsukasa transforms into a long black sickle blade connected to Black☆Star's shadow by an extended chain. Black☆Star can wield it at close range or throw it toward distant opponents while controlling its trajectory through the chain.", "continuity": "Manga", "image_url": "/abilities/shadow-star-first-form.png"},
    {"id": 25, "name": "Shadow☆Star Second Form: \"Leaf of the Moonlit Night\"", "category": "Soul Resonance", "users": [["Black☆Star", "Tsubaki Nakatsukasa"]], "description": "A Shadow☆Star Form technique in which Tsubaki Nakatsukasa transforms into a large four-pointed shuriken infused with the Uncanny Sword's power. Black☆Star can throw it at high speed to cut through attacks and hardened defenses, or release a burst of Soul Wavelength energy that extends its blades for a more powerful close-range strike.", "continuity": "Manga", "image_url": "/abilities/shadow-star-second-form.png"},
    {"id": 26, "name": "Shadow☆Star Third Form: \"Severed Shadow\"", "category": "Soul Resonance", "users": [["Black☆Star", "Tsubaki Nakatsukasa"]], "description": "A Shadow☆Star Form technique in which Tsubaki Nakatsukasa transforms into a large kunai-like dagger infused with the Uncanny Sword's power. The technique grants Black☆Star extraordinary speed, leaving behind afterimages known as severed shadows that retain traces of real matter and can mislead or obstruct opponents during combat.", "continuity": "Manga", "image_url": "/abilities/shadow-star-third-form.png"},
    {"id": 27, "name": "Shadow☆Star Fourth Form: \"Branched Darkness\"", "category": "Soul Resonance", "users": [["Black☆Star", "Tsubaki Nakatsukasa"]], "description": "A Shadow☆Star Form technique in which Tsubaki Nakatsukasa transforms into Black☆Star himself by drawing upon his Soul Wavelength. Primarily intended for deception and infiltration, the technique allows the pair to create convincing decoys for stealth and surprise attacks rather than direct combat.", "continuity": "Manga", "image_url": "/abilities/shadow-star-fourth-form.png"},
    {"id": 28, "name": "Transformation Magic", "category": "Magic", "users": [["Blair"], ["Eruka Frog"], ["Mizune Family"], ["Kimial Diehl"]], "description": "A transformation spell that allows the user to alter their appearance or assume entirely different forms, ranging from humans to animals or other beings. The forms available typically reflect the user's magical nature or chosen theme.", "continuity": "Manga and Anime", "image_url": "/abilities/transformation-magic.png"},
    {"id": 29, "name": "Speed☆Star", "category": "Weapon Ability", "users": [["Black☆Star", "Tsubaki Nakatsukasa"]], "description": "A high-speed technique performed while wielding Tsubaki Nakatsukasa's Ninja Sword form. It greatly increases the user's movement speed, allowing rapid attacks, evasive maneuvers, and close-quarters combat. The technique relies on friction for movement and can backfire if traction is insufficient.", "continuity": "Manga and Anime", "image_url": "/abilities/speed-star.png"},
    {"id": 30, "name": "Shield☆Star", "category": "Soul Resonance", "users": [["Black☆Star", "Tsubaki Nakatsukasa"]], "description": "A defensive Soul Resonance technique performed while Tsubaki is in her Chain Scythe form. The technique creates a large pentagram-shaped energy shield capable of blocking powerful attacks, including strikes from Demon Weapons.", "continuity": "Manga and Anime", "image_url": "/abilities/shield-star.png"},
    {"id": 31, "name": "Black Blood", "category": "Black Blood", "users": [["Crona"], ["Ragnarok"], ["Soul Eater Evans"], ["Maka Albarn"], ["Asura"], ["Black Clown"]], "description": "An artificial blood substance created by Medusa that greatly increases durability, supports the user's body and carries a powerful madness wavelength.", "continuity": "Manga and Anime", "image_url": "/abilities/black-blood.png"},
    {"id": 32, "name": "Black Blood Armor", "category": "Black Blood", "users": [["Maka Albarn", "Soul Evans"], ["Crona", "Ragnarok", "Black Clown"]], "description": "A defensive technique that hardens Black Blood throughout or around the body to reduce damage from physical attacks.", "continuity": "Manga and Anime", "image_url": "/abilities/black-blood-armor.png"},
    {"id": 33, "name": "Bloody Needle", "category": "Black Blood", "users": [["Crona", "Ragnarok"]], "description": "A technique that hardens drops of spilled Black Blood into sharp needles that erupt toward and pierce an opponent.", "continuity": "Manga and Anime", "image_url": "/abilities/bloody-needle.png"},
    {"id": 34, "name": "Bloody Slicer", "category": "Black Blood", "users": [["Crona"]], "description": "A curved projectile created by releasing Black Blood and hardening it into a fast-moving cutting blade.", "continuity": "Manga and Anime", "image_url": "/abilities/blood-slicer.png"},
    {"id": 35, "name": "Bloody Lance", "category": "Black Blood", "users": [["Crona"]], "description": "A Black Blood technique that creates long hardened spikes or lances capable of piercing targets from a distance.", "continuity": "Manga and Anime", "image_url": "/abilities/bloody-lance.png"},
    {"id": 36, "name": "Bloody Coat", "category": "Black Blood", "users": [["Crona", "Ragnarok", "Black Clown"]], "description": "A defensive layer of hardened Black Blood that surrounds Crona's body like protective clothing or armor.", "continuity": "Manga", "image_url": "/abilities/bloody-coat.png"},
    {"id": 37, "name": "Magic Stimulant Boost", "category": "Magic", "users": [["Shaula Gorgon"]], "description": "An anime-exclusive magic spell that amplifies the effects of Shaula Gorgon's poison. By releasing her magic over a wide area, the technique reactivates poisoned victims, greatly increasing their strength and aggression while allowing Shaula to seize control of those affected by her secondary infection.", "continuity": "Anime", "image_url": "/abilities/magic-stimulant-boost.png"},
    {"id": 38, "name": "Resonance by Black Blood", "category": "Soul Resonance", "users": [["Maka Albarn", "Soul Eater Evans"]], "description": "A Soul Resonance technique that utilizes Black Blood to greatly amplify the synchronization between Maka Albarn and Soul Eater Evans. While it produces a much stronger resonance than normal, prolonged use can consume the meister's sanity and even endanger their soul.", "continuity": "Manga", "image_url": "/abilities/resonance-black-blood.png"},
    {"id": 39, "name": "Scream Resonance", "category": "Soul Resonance", "users": [["Crona", "Ragnarok"]], "description": "A unique Soul Resonance technique in which Ragnarok resonates with Crona and releases powerful screams resembling ultrasonic sound waves. The resonance greatly amplifies Ragnarok's offensive power and can damage ordinary weapons during transformation.", "continuity": "Manga and Anime", "image_url": "/abilities/scream-resonance.png"},
    {"id": 40, "name": "Screech Alpha", "category": "Soul Resonance", "users": [["Crona", "Ragnarok"]], "description": "A Soul Resonance technique in which Crona and Ragnarok launch a massive mouth-shaped projectile that travels toward its target before exploding on contact. The attack can also be performed in stronger forms through transformations such as the Black Dragon and Kishin forms.", "continuity": "Manga and Anime", "image_url": "/abilities/screech-alpha.png"},
    {"id": 41, "name": "Screech Beta", "category": "Soul Resonance", "users": [["Crona", "Ragnarok"]], "description": "A Soul Resonance technique in which Crona and Ragnarok unleash a large mouth-shaped slash that follows the arc of Ragnarok's swing. Unlike Screech Alpha, the attack forms along the weapon's path, creating a wide cutting wave capable of striking multiple targets.", "continuity": "Manga and Anime", "image_url": "/abilities/screech-beta.png"},
    {"id": 42, "name": "Screech Gamma", "category": "Soul Resonance", "users": [["Crona", "Ragnarok"]], "description": "A Soul Resonance technique in which Crona and Ragnarok transform Ragnarok's blade into a larger, mouth-shaped weapon before unleashing a rapid barrage of sound-infused slashes. The attack generates successive sound waves capable of damaging both opponents and their Demon Weapons while overwhelming conventional defenses.", "continuity": "Manga and Anime", "image_url": "/abilities/screech-gamma.png"},
    {"id": 43, "name": "Screech Delta", "category": "Soul Resonance", "users": [["Crona", "Ragnarok"]], "description": "A Soul Resonance technique performed while Crona, Ragnarok, and the Black Clown are united through Madness Fusion. By wielding three swords simultaneously, Crona unleashes Screech Alpha in multiple directions, creating a devastating tornado of solid Black Shockwaves capable of striking from every angle.", "continuity": "Manga", "image_url": "/abilities/screech-delta.png"},
    {"id": 44, "name": "Madness of Black Blood", "category": "Madness", "users": [["Crona"], ["Ragnarok"], ["Soul Eater Evans"], ["Maka Albarn"]], "description": "The madness contained within Black Blood, which heightens aggression, distorts perception and attempts to influence the mind of its host.", "continuity": "Manga and Anime", "image_url": "/abilities/madness-black-blood.png"},
    {"id": 45, "name": "Merge", "category": "Magic", "users": [["Mizune Family"], ["Noah (Wrath)"]], "description": "A magic technique that allows two or more beings to fuse into a single entity, combining their bodies and magical power. The resulting form is typically stronger than its individual components and can be used to create larger or more powerful composite beings.", "continuity": "Manga and Anime", "image_url": "/abilities/merge.png"},
    {"id": 46, "name": "First Line of Sanzu: Release", "category": "reaper power", "users": [["Death the Kid"]], "description": "A technique that releases the power of Kid's first connected Line of Sanzu, greatly increasing his power and damaging the surrounding area.", "continuity": "Manga", "image_url": "/abilities/first-line-sanzu-release.png"},
    {"id": 47, "name": "Death Cannon", "category": "Soul Resonance", "users": [["Death the Kid", "Liz Thompson", "Patty Thompson"]], "description": "A Soul Resonance technique in which Liz and Patty transform into large cannon-like weapons that fire powerful blasts of soul wavelength.", "continuity": "Manga and Anime", "image_url": "/abilities/death-cannon.png"},
    {"id": 48, "name": "Death Eagle .42", "category": "Soul Resonance", "users": [["Death the Kid", "Liz Thompson", "Patty Thompson"]], "description": "An advanced transformation of the Demon Twin Guns activated after Kid connects a Line of Sanzu and resonates with Liz and Patty.", "continuity": "Manga", "image_url": "/abilities/death-eagle.png"},
    {"id": 49, "name": "Sanzu River Shot", "category": "Weapon Ability", "users": [["Death the Kid", "Liz Thompson", "Patty Thompson"]], "description": "A Weapon Ability performed by Death the Kid with Liz Thompson and Patty Thompson in their Demon Twin Guns forms. The technique unleashes a rapid barrage of Soul Wavelength bullets capable of overwhelming opponents, with a variation firing three successive shots in quick succession.", "continuity": "Manga and Anime", "image_url": "/abilities/sanzu-river-shot.png"},
    {"id": 50, "name": "Sanzu Falls Shot", "category": "Reaper Power", "users": [["Death the Kid"]], "description": "A Reaper Power technique performed after Death the Kid connects the first Line of Sanzu. Kid fires a continuous stream of Soul Wavelength energy downward while lowering and spreading his arms, creating a waterfall-like barrage capable of striking multiple targets over a wide area.", "continuity": "Manga", "image_url": "/abilities/sanzu-falls-shot.png"},   
    {"id": 51, "name": "Parent's Seven Rays", "category": "reaper power", "users": [["Death the Kid", "Liz Thompson", "Patty Thompson"]], "description": "One of Kid's strongest techniques, performed through Execution Mode, a connected Line of Sanzu and the Death Eagle .42 transformation.", "continuity": "Manga", "image_url": "/abilities/parent-seven-ray.png"},
    {"id": 52, "name": "Mind Attack", "category": "Magic", "users": [["Arachne Gorgon"]], "description": "A magic technique that attacks a target's mind by exploiting their emotional weaknesses and negative thoughts, attempting to break their will and turn them against their allies. The spell can be resisted or dispelled by those possessing an Anti-Demon Wavelength.", "continuity": "Manga", "image_url": "/abilities/mind-attack.png"},
    {"id": 53, "name": "Death Claw", "category": "reaper power", "users": [["Lord Death"], ["Death the Kid"]], "description": "A Grim Reaper technique in which Death manifests a large claw-like hand to seize or attack a target.", "continuity": "Manga and Anime", "image_url": "/abilities/death-claw.png"},
    {"id": 54, "name": "Death Block", "category": "reaper power", "users": [["Lord Death"]], "description": "A defensive Grim Reaper technique used to stop or repel an incoming attack.", "continuity": "Manga and Anime", "image_url": "/abilities/death-block.png"},
    {"id": 55, "name": "Death Arm Blocking", "category": "reaper power", "users": [["Death the Kid"]], "description": "A defensive technique in which Death uses his enlarged reaper arms to intercept and withstand an attack.", "continuity": "Manga and Anime", "image_url": "/abilities/death-arm-blocking.png"},
    {"id": 56, "name": "Shinigami Chop", "category": "Martial Art", "users": [["Lord Death"]], "description": "One of Death's signature close-range techniques in which he delivers a powerful karate chop. Depending on the force used, it can serve as a harmless disciplinary strike or a devastating attack capable of injuring even powerful opponents.", "continuity": "Manga and Anime", "image_url": "/abilities/shinigami-chop.png"},
    {"id": 57, "name": "Shinigami Shockwave", "category": "Reaper Power", "users": [["Lord Death"]], "description": "A Reaper technique that releases powerful waves of electricity toward the target. After performing Katsu, Death projects an electrical shockwave capable of damaging powerful opponents and destroying supernatural defenses.", "continuity": "Manga and Anime", "image_url": "/abilities/shinigami-shockwave.png"},
    {"id": 58, "name": "Reaper Eyes", "category": "Sensory Ability", "users": [["Lord Death"], ["Death the Kid"]], "description": "A Grim Reaper trait that allows the user to produce an intimidating supernatural gaze associated with their reaper power.", "continuity": "Manga and Anime", "image_url": "/abilities/reaper-eyes.png"},
    {"id": 59, "name": "Vector Arrow", "category": "Magic", "users": [["Medusa Gorgon"]], "description": "Medusa creates arrow-shaped vectors that travel through the air and pierce or strike her opponents.", "continuity": "Manga and Anime", "image_url": "/abilities/vector-arrow.png"},
    {"id": 60, "name": "Vector Plate", "category": "Magic", "users": [["Medusa Gorgon"]], "description": "Medusa places directional arrow plates on surfaces that rapidly propel anything touching them in the direction of the arrow.", "continuity": "Manga and Anime", "image_url": "/abilities/vector-plate.png"},
    {"id": 61, "name": "Vector Storm", "category": "Magic", "users": [["Medusa Gorgon"]], "description": "A large-scale attack in which Medusa releases numerous magical vectors to surround and overwhelm an opponent.", "continuity": "Manga and Anime", "image_url": "/abilities/vector-storm.png"},
    {"id": 62, "name": "Snake Bomb", "category": "Magic", "users": [["Medusa Gorgon"]], "description": "A spell that places magical snakes inside a target and allows Medusa to detonate or activate them later.", "continuity": "Manga and Anime"},
    {"id": 63, "name": "Body Possession", "category": "Magic", "users": [["Medusa Gorgon"]], "description": "A spell that allows Medusa's soul to enter and take control of another person's body after the loss of her original body.", "continuity": "Manga and Anime", "image_url": "/abilities/body-possession.png"},
    {"id": 64, "name": "Light Refraction", "category": "Soul Resonance", "users": [["Alexandre", "Dengu Dinga"]], "description": "A defensive Soul Resonance technique performed by Alexandre and Dengu Dinga that manipulates light to bend the trajectory of incoming beam attacks, causing them to curve harmlessly around the user as if blocked by an invisible barrier. The technique is ineffective against attacks the user cannot anticipate.", "continuity": "Manga", "image_url": "/abilities/light-refraction.png"},
    {"id": 65, "name": "Infinite Propagation", "category": "Defense Ability", "users": [["Clowns"]], "description": "A regenerative ability possessed by Clowns that allows them to recover from fatal injuries by drawing upon the infinite Madness generated by Asura's wavelength. Regeneration requires assistance from another Clown and can be disrupted by certain forms of magic that block the transmission of Madness.", "continuity": "Manga", "image_url": "/abilities/infinite-propagation.png"},
    {"id": 66, "name": "Arachne's Madness", "category": "Madness", "users": [["Arachne Gorgon"]], "description": "A form of madness associated with Arachne that manipulates perception and creates an overwhelming sense of control and entrapment.", "continuity": "Manga", "image_url": "/abilities/arachne-madness.png"},
    {"id": 67, "name": "Madness Wavelength", "category": "Madness", "users": [["Lord Death"], ["Asura"], ["Eibon"], ["Excalibur"], ["Great Old One of Power"], ["Kaguya"], ["Moonlight"], ["White Rabbit"], ["Crona"], ["Ragnarok"], ["Arachne Gorgon"], ["Soul Eater Evans"]], "description": "A soul wavelength that spreads madness to nearby people, intensifying emotions such as fear, obsession, aggression and paranoia.", "continuity": "Manga and Anime", "image_url": "/abilities/madness-wavelength.png"},
    {"id": 68, "name": "Madness of Fear", "category": "Madness", "users": [["Asura"], ["Clowns"]], "description": "Asura's dominant form of madness, which magnifies fear and causes people exposed to his wavelength to experience panic and hallucinations.", "continuity": "Manga and Anime", "image_url": "/abilities/madness-of-fear.png"},
    {"id": 69, "name": "Madness of Order", "category": "Madness", "users": [["Lord Death"], ["Death the Kid"]], "description": "A form of madness associated with absolute order and symmetry that can suppress individuality and impose rigid control.", "continuity": "Manga", "image_url": "/abilities/madness-of-order.png"},
    {"id": 70, "name": "Madness Fusion", "category": "Soul Ability", "users": [["Justin Law", "The Clown"], ["Medusa Gorgon", "The Purple-Dyed Clown"], ["Crona", "Ragnarok", "The Black Clown"]], "description": "A transformation technique in which a Clown physically fuses with a subject, using the Clown's concentrated Madness to drastically enhance the subject's power and alter their body. The resulting form varies by user and can provide major offensive, defensive, regenerative, or Black Blood-based abilities.", "continuity": "Manga", "image_url": "/abilities/madness-fusion.png"},
    {"id": 71, "name": "Requiem of Madness", "category": "Magic", "users": [["Arachne Gorgon"]], "description": "A magical technique developed by Arachne Gorgon that transforms her body into living madness. In this form she gains intangibility, spider-like abilities, and can spread madness over a wide area, absorb kishin-related power, and employ techniques such as Madness Attack.", "continuity": "Manga", "image_url": "/abilities/requiem-of-madness.png"},
    {"id": 72, "name": "Kishin Power", "category": "Madness", "users": [["Asura"]], "description": "The supernatural power possessed by a Kishin, combining an immense soul, physical strength, madness and unusual regenerative abilities.", "continuity": "Manga and Anime"},
    {"id": 73, "name": "Regeneration", "category": "Support Ability", "users": [["Lord Death"], ["Death the Kid"], ["Asura"], ["Free"], ["Alone"]], "description": "A supernatural ability that allows the user to regenerate lost or destroyed body parts by replacing them with new ones. The extent and speed of regeneration varies depending on the individual.", "continuity": "Manga and Anime", "image_url": "/abilities/regeneration.png"},
    {"id": 74, "name": "Immortality", "category": "Defense Ability", "users": [["Free"], ["Alone"], ["Lord Death"], ["Asura"]], "description": "A supernatural ability that prevents the user from being killed through ordinary means, grants extreme longevity, and allows recovery from severe injuries. The exact limitations vary by the user's nature, as members of the Immortal Clan and Death Gods possess different forms of immortality.", "continuity": "Manga and Anime", "image_url": "/abilities/immortality.png"},
    {"id": 75, "name": "Ice Magic", "category": "Magic", "users": [["Free"]], "description": "Free's magical ability to create, shape and control ice for projectiles, restraints, defensive structures and large-scale attacks.", "continuity": "Manga and Anime", "image_url": "/abilities/ice-magic.png"},
    {"id": 76, "name": "Spatial Magic", "category": "Magic", "users": [["Free"], ["Maba"], ["Eibon"], ["Sofia Ressa Valk II"]], "description": "Magic that manipulates space, allowing Free to create portals and move himself or others between distant locations.", "continuity": "Manga and Anime", "image_url": "/abilities/spatial-magic.png"},
    {"id": 77, "name": "Magic Eye", "category": "Magic", "users": [["Free"], ["Grand Witch"]], "description": "A powerful magical eye stolen from Mabaa that grants Free access to advanced spatial and ice-based magical techniques.", "continuity": "Manga and Anime", "image_url": "/abilities/magic-eye.png"},
    {"id": 78, "name": "Pelt of the Fire Rat", "category": "Magic", "users": [["Kaguya"]], "description": "A Wardrobe Change spell that equips Kaguya with the Pelt of the Fire Rat, a large fur garment that alters her appearance and grants access to additional magical abilities and techniques associated with the outfit.", "continuity": "Manga", "image_url": "/abilities/pelt-fire-rat.png"},
    {"id": 79, "name": "Pumpkin Cannon", "category": "Magic", "users": [["Blair"]], "description": "Blair creates a large pumpkin-shaped magical projectile or cannon that fires an explosive blast at her target.", "continuity": "Manga and Anime", "image_url":"/abilities/pumpkin-cannon.png"},
    {"id": 80, "name": "Smashing Pumpkin", "category": "Magic", "users": [["Blair"]], "description": "A destructive pumpkin-themed spell used by Blair to strike or crush an opponent with magical force.", "continuity": "Manga and Anime", "image_url": "/abilities/smashing-pumpkin.png"},
    {"id": 81, "name": "Tadpole Bomb", "category": "Magic", "users": [["Eruka Frog"]], "description": "Eruka creates explosive tadpole-shaped magical bombs that move toward their targets before detonating.", "continuity": "Manga and Anime", "image_url": "/abilities/tadpole-bomb.png"},
    {"id": 82, "name": "Scorpion Scissors", "category": "Magic", "users": [["Shaula Gorgon"]], "description": "A direct attack spell in which Shaula Gorgon conjures two enormous magical scorpion tails before crossing and sweeping them like a pair of scissors to slash through her target with a powerful cutting attack.", "continuity": "Soul Eater NOT!", "image_url": "/abilities/scorpion-scissors.png"},
    {"id": 83, "name": "Shield Phaser", "category": "Magic", "users": [["Sofia Valk"]], "description": "A defensive magic spell that conjures a magical shield to protect the user from incoming attacks. The shield's durability and defensive strength depend on the user's magical power, allowing it to withstand increasingly powerful assaults.", "continuity": "Special Social Studies Field Trip", "image_url": None},
    {"id": 84, "name": "Soul Hack", "category": "Support Ability", "users": [["Soul Eater Evans", "Maka Albarn"]], "description": "A variation of Noise Cancelling in which Soul uses Soul's Piano together with Maka Albarn's Soul Perception to synchronize with an opponent's soul wavelength. By matching the rhythm of an incoming attack, the user can seize control of it and redirect it against the enemy.", "continuity": "Manga", "image_url": "/abilities/soul-hack.png"},
    {"id": 85, "name": "Collect", "category": "Reaper Power", "users": [["Lord Death"], ["Death the kid"]], "description": "A Reaper ability that allows the user to collect the souls of other beings and store them within their body, either by consuming them directly or drawing them toward themselves.", "continuity": "Manga", "image_url": "/abilities/collect.png"},    
    {"id": 86, "name": "Confiscation", "category": "Book of Eibon Ability", "users": [["Lord Death"], ["Death the Kid"]], "description": "A supernatural technique associated with the Book of Eibon that takes possession of a target or removes it from its current location.", "continuity": "Manga"},
    {"id": 87, "name": "Silver Gun", "category": "Weapon Ability", "users": [["Justin Law"]], "description": "An advanced guillotine technique performed by Justin Law while in Madness Fusion. After restraining multiple opponents with chained head restraints, Justin summons numerous guillotine blades to execute simultaneous strikes across a wide area.", "continuity": "Manga", "image_url": "/abilities/silver-gun.png"},
    {"id": 88, "name": "Marionette's Rain", "category": "Soul Ability", "users": [["Masamune Nakatsukasa"]], "description": "A Shadow technique in which Masamune Nakatsukasa creates numerous Shadow Puppets that emerge from the surrounding area to restrain or repeatedly pierce an opponent. The attack is performed within his internal shadow dimension, allowing the puppets to strike from multiple directions.", "continuity": "Manga and Anime", "image_url": "/abilities/marionette-rain.png"},
    {"id": 89, "name": "Saw Leg", "category": "Weapon Ability", "users": [["Giriko"]], "description": "A partial Demon Weapon transformation that turns Giriko's legs into chainsaw blades. The style uses a gear-based system that increases the power of his attacks across multiple levels and can also be used like motorized roller blades to greatly enhance his movement speed.", "continuity": "Manga and Anime", "image_url": "/abilities/saw-leg.png"},
    {"id": 90, "name": "Saw Hair", "category": "Weapon Ability", "users": [["Giriko"]], "description": "A Weapon Ability that allows Giriko to transform his hair into chainsaw-like blades. The saws can extend in length and be manipulated to slash, overwhelm, and attack opponents from multiple directions.", "continuity": "Manga", "image_url": "/abilities/saw-hair.png"},
    {"id": 91, "name": "Saw Leg Third Gear: Wave of Slaughter", "category": "Weapon Ability", "users": [["Giriko"]], "description": "A Weapon Ability performed while using Saw Leg's Third Gear. Giriko launches into the air before delivering a powerful downward kick with his chainsaw leg, releasing a devastating vertical strike that maximizes the destructive force of Third Gear.", "continuity": "Manga and Anime", "image_url": "/abilities/saw-leg-third-gear.png"},
    {"id": 92, "name": "Senrigan", "category": "Sensory Ability", "users": [["Azusa Yumi"]], "description": "A long-range spatial awareness ability that allows Azusa to map distant areas and accurately locate people and objects.", "continuity": "Manga and Anime", "image_url": "/abilities/senrigan.png"},
    {"id": 93, "name": "Solar Ray", "category": "Weapon Ability", "users": [["Tezca Tlipoca"]], "description": "A technique in which Tezca Tlipoca creates a series of mirrors across his body to concentrate sunlight into a single focal point, releasing a devastating beam of intense solar energy capable of incinerating targets.", "continuity": "Manga", "image_url": "/abilities/solar-ray.png"},
    {"id": 94, "name": "Shrink", "category": "Magic", "users": [["Blair"]], "description": "A utility magic spell that allows Blair to reduce the size of a chosen object by pointing at it and reciting a mantra. The spell can be cast from a distance, causing the targeted object to instantly shrink.", "continuity": "Manga and Anime", "image_url": "/abilities/shrink.png"},
    {"id": 95, "name": "Lightning King", "category": "Weapon Ability", "users": [["Ox Ford", "Harvar D. Éclair"]], "description": "A weapon technique in which Ox Ford pierces the target with Harvar D. Éclair in his Lightning Spear form before releasing a powerful electrical shock capable of incapacitating the opponent.", "continuity": "Manga and Anime", "image_url": "/abilities/lightning-king.png"},
    {"id": 96, "name": "Lightning King Drill", "category": "Weapon Ability", "users": [["Ox Ford", "Harvar D. Éclair"]], "description": "A Weapon Ability performed by Ox Ford with Harvar D. Éclair in his Lightning Spear form. The technique launches a high-speed, lightning-charged thrust that drills through the target with a blade of electricity moving at the speed of light.", "continuity": "Manga and Anime", "image_url": "/abilities/lightning-king-drill.png"},
    {"id": 97, "name": "Lightning King Quake", "category": "Weapon Ability", "users": [["Ox Ford", "Harvar D. Éclair"]], "description": "A Weapon Ability performed by Ox Ford with Harvar D. Éclair in his Lightning Spear form. By spinning the spear before driving it into the ground with a powerful stomp, the technique channels lightning through the earth to electrocute the target.", "continuity": "Manga", "image_url": "/abilities/lightning-king-quake.png"},
    {"id": 98, "name": "Lightning Rope", "category": "Weapon Ability", "users": [["Franken Stein", "Marie Mjolnir"]], "description": "A Weapon Ability performed by Franken Stein and Marie Mjolnir in which Mjolnir wraps around the meister to form an electrical bind, using hyper-nerve induction to stimulate the user's motor system and dramatically enhance physical speed and reflexes. Prolonged use places severe strain on the user's body and nervous system.", "continuity": "Manga", "image_url": "/abilities/lightning-rope.png"},
    {"id": 99, "name": "Izuna", "category": "Soul Resonance", "users": [["Marie Mjolnir", "Franken Stein"]], "description": "A lightning-based resonance technique in which Marie's hammer wavelength electrifies Stein's body and attacks.", "continuity": "Manga", "image_url": "/abilities/izuna.png"},
    {"id": 100, "name": "Noise Cancelling", "category": "Soul Ability", "users": [["Soul Eater Evans", "Maka Albarn"]], "description": "A wavelength-based technique in which Soul Eater Evans plays the piano within the Black Room to emit a Soul Wavelength opposite to an opponent's frequency, disrupting their wavelength and potentially incapacitating them. Soul requires resonance with Maka Albarn and her Soul Perception to identify the correct frequency, though stronger opposing wavelengths can cause the technique to backfire.", "continuity": "Manga", "image_url": "/abilities/noise-cancelling.png"},
    {"id": 101, "name": "Soul's Piano", "category": "Support Ability", "users": [["Soul Evans"]], "description": "A spiritual piano manifested within Soul Evans' soul after his exposure to the Black Blood. It allows the user to transmit and manipulate soul wavelengths through music, enabling advanced techniques such as Soul Meditation, Soul Adagio, and Soul Hack, while also influencing Black Blood and Soul Resonance.", "continuity": "Manga and Anime", "image_url": "/abilities/soul-piano.png"},
    {"id": 102, "name": "Soul Adagio", "category": "Support Ability", "users": [["Soul Eater Evans", "Maka Albarn"]], "description": "A variation of Noise Cancelling in which Soul uses Soul's Piano together with Maka Albarn's Soul Perception to emit a soul wavelength opposite to the target's own. The opposing wavelengths interfere with one another, slowing or suppressing the target's movements and leaving them in a lethargic, trance-like state.", "continuity": "Manga", "image_url": "/abilities/soul-adagio.png"},
    {"id": 103, "name": "Absorb", "category": "Weapon Ability", "users": [["Demon Weapons"]], "description": "A technique that allows Demon Weapons to absorb the souls or powers of other beings, typically through consumption or their weapon form.", "continuity": "Manga and Anime", "image_url": "/abilities/absorb.png"},
    {"id": 104, "name": "Addition Mode", "category": "Sword Technique", "users": [["Mifune"]], "description": "An offensive sword technique of the Infinite One-Sword Style in which the user delivers rapid consecutive strikes after an initial swing, inflicting multiple cuts in quick succession.", "continuity": "Manga and Anime", "image_url": "/abilities/addition-mode.png"},
    {"id": 105, "name": "AFX-T", "category": "Soul Resonance", "users": [["Kirikou Rung", "Fire", "Thunder"]], "description": "A soul resonance technique that combines the powers of Fire and Thunder to create a large ball of explosive energy before launching it at the target.", "continuity": "Manga and Anime", "image_url": "/abilities/AFX-T.png"},
    {"id": 106, "name": "Augment", "category": "Magic", "users": [["Noah (Greed)"]], "description": "A magical technique that allows the user to imbue others with magical power, granting them access to a unique form of magic.", "continuity": "Manga", "image_url": "/abilities/augment.png"},
    {"id": 107, "name": "Barrier", "category": "Magic", "users": [["Lord Death"], ["Free"], ["Asura"], ["Maba"]], "description": "A magical technique that creates a supernatural barrier capable of preventing or restricting movement. Barrier properties vary depending on the user's magic or abilities.", "continuity": "Manga and Anime", "image_url": "/abilities/barrier.png"},
    {"id": 108, "name": "Bind Ivy", "category": "Weapon Ability", "users": [["Jinn Galland", "Zubaidah"]], "description": "A technique used while Jinn Galland is in his Tower form, allowing him to manipulate a large mass of ivy to restrain an opponent's arms, back, and movement.", "continuity": "Manga", "image_url": "/abilities/bind-ivy.png"},
    {"id": 109, "name": "Carcan Bras", "category": "Weapon Ability", "users": [["Justin Law"]], "description": "A transformation-based immobilization technique in which Justin Law transforms his left arm into the headlock component of his guillotine weapon form to restrain an opponent.", "continuity": "Manga and Anime", "image_url": "/abilities/carcan-bras.png"},
    {"id": 110, "name": "Chain", "category": "Weapon Ability", "users": [["Giriko"]], "description": "A defensive technique that allows Giriko to manifest chains from his chainsaw weapon form, creating durable chain armor and extending chains to restrain or attack opponents.", "continuity": "Manga and Anime", "image_url": "/abilities/chain.png"},
    {"id": 111, "name": "Change \"Pixie\"", "category": "Weapon Ability", "users": [["Jacqueline O'Lantern Dupré", "Kim Diehl"]], "description": "A transformation technique that changes Jacqueline O'Lantern Dupré into a rocket-powered lantern, allowing Kim Diehl to fly at high speeds while sacrificing offensive capabilities.", "continuity": "Manga and Anime", "image_url": "/abilities/change-pixie.png"},
    {"id": 112, "name": "Clowning Mind's Eye", "category": "Weapon Ability", "users": [["Boris Factory Clown"]], "description": "A projectile technique in which the user launches its nose at an opponent, creating a powerful explosion on impact capable of causing widespread destruction.", "continuity": "Manga", "image_url": "/abilities/clowning-minds-eye.png"},
    {"id": 113, "name": "Conan the Great", "category": "Weapon Ability", "users": [["Black☆Star"]], "description": "A powerful sword technique performed while wielding Tsubaki Nakatsukasa in her Uncanny Sword form, delivering a devastating downward slash from above or directly at the target.", "continuity": "Manga and Anime", "image_url": "/abilities/conan-the-great.png"},
    {"id": 114, "name": "Curtain of Muscle", "category": "Defense Ability", "users": [["Mosquito"]], "description": "A defensive technique that hardens the user's muscles, greatly increasing durability and allowing them to withstand powerful attacks, including Soul Resonance and Demon Weapon strikes.", "continuity": "Manga and Anime", "image_url": "/abilities/curtain-of-muscle.png"},
    {"id": 115, "name": "Darkness Discord", "category": "Magic", "users": [["Mosquito"]], "description": "A sound-based magical attack that traps opponents within a vortex of bats before bombarding them with powerful ultrasonic waves, causing severe internal damage.", "continuity": "Manga", "image_url": "/abilities/darkness-discords.png"},
    {"id": 116, "name": "Death in the Otherworld", "category": "Weapon Ability", "users": [["Death the Kid"]], "description": "A Demon Twin Guns technique in which Death the Kid crosses his arms and fires a powerful concussive shot in both directions, allowing him to strike two adjacent opponents at once.", "continuity": "Manga and Anime", "image_url": "/abilities/death-otherworld.png"},
    {"id": 117, "name": "Death Slide", "category": "Weapon Ability", "users": [["Death the Kid"]], "description": "A movement technique in which Death the Kid uses Beelzebub as a skateboard to grind along linear attacks or magical projectiles, allowing him to evade or traverse them with speed.", "continuity": "Manga and Anime", "image_url": "/abilities/death-slide.png"},
    {"id": 118, "name": "Decoy", "category": "Support Ability", "users": [["Asura"]], "description": "A technique that allows the user to instantly create a false clone of themselves, enabling them to evade attacks or deceive opponents before the decoy quickly dissipates.", "continuity": "Anime", "image_url": "/abilities/decoy.png"},
    {"id": 119, "name": "Double T", "category": "Soul Resonance", "users": [["Kirikou Rung", "Fire", "Thunder"]], "description": "A Soul Resonance technique in which Kirikou Rung first launches Fire at the opponent before Thunder leaps into the air, forming a lightning bolt-shaped trajectory and crashing into the ground to create a powerful radial shockwave of electricity.", "continuity": "Manga", "image_url": "/abilities/double-t.png"},
    {"id": 120, "name": "Drunken Fist", "category": "Martial Art", "users": [["Meme Tatane"], ["Shaula Gorgon", "Meme Tatane"]], "description": "A fighting style based on drunken boxing that uses loose, unpredictable movements, strong reflexes, and sudden changes in momentum to evade attacks and overwhelm opponents. Meme Tatane can use the style unconsciously while asleep, while Shaula Gorgon can also perform it while possessing Meme's body.", "continuity": "Manga and Anime", "image_url": "/abilities/drunken-fist.png"},
    {"id": 121, "name": "Death God Taijutsu: \"Crime\" Stance", "category": "Martial Art", "users": [["Death the Kid"]], "description": "A stance from Death the Kid's Death God Taijutsu that emphasizes swift movement, powerful strikes, and precise timing. The user turns their body sideways while adopting a balanced posture that can be used alone or in combination with the Demon Twin Guns or Tonfas.", "continuity": "Manga", "image_url": "/abilities/crime-stance.png"},
    {"id": 122, "name": "Death God Taijutsu: \"Mad Crime\" Stance", "category": "Martial Art", "users": [["Death the Kid"]], "description": "An advanced stance of Death the Kid's Death God Taijutsu that can only be initiated while under the influence of Madness. It emphasizes relentless close-quarters offense, fluid counterattacks, and precise exploitation of an opponent's openings through rapid strikes and agile movement.", "continuity": "Manga", "image_url": "/abilities/mad-crime.png"},
    {"id": 123, "name": "Death God Taijutsu: \"Punishment\" Stance", "category": "Martial Art", "users": [["Death the Kid"]], "description": "A defensive stance of Death the Kid's Death God Taijutsu that allows the user to anticipate, interpret, and counter an opponent's movements while maintaining a connected Line of Sanzu. It can be used with the Demon Twin Guns and incorporates the Death Arm Blocking technique to deflect incoming attacks.", "continuity": "Manga", "image_url": "/abilities/punishment-stance.png"},
    {"id": 124, "name": "E3", "category": "Soul Resonance", "users": [["Kirikou Rung", "Fire", "Thunder", "Kim Diehl", "Jacqueline O'Lantern Dupré", "Liz Thompson", "Patty Thompson"]], "description": "A large-scale Tag-Team Soul Resonance performed by Kirikou Rung, Fire, Thunder, Kim Diehl, Jacqueline O'Lantern Dupré, Liz Thompson, and Patty Thompson. By combining the powers of the Demon Twin Guns, Demon Pots, and Demon Lantern with Fire and Thunder's awakened Earth Shaman abilities, the technique unleashes a massive beam of energy infused with lightning and fire.", "continuity": "Manga", "image_url": "/abilities/e3.png"},
    {"id": 125, "name": "Evaporation", "category": "Support Ability", "users": [["Flying Dutchman"], ["Black Clown"], ["White Rabbit"]], "description": "A phasing ability that allows the user to pass harmlessly through solid matter such as walls, floors, and the ground. Primarily used for movement, infiltration, and stealth, the technique does not provide protection against direct physical attacks.", "continuity": "Manga and Anime", "image_url": "/abilities/evap.png"},
    {"id": 126, "name": "Experimental Ectoplasm", "category": "Soul Resonance", "users": [["Franken Stein", "Spirit Albarn"]], "description": "A Soul Resonance technique in which Franken Stein and Spirit Albarn generate a massive marshmallow-like ectoplasmic body that expands to several times the user's size, temporarily shielding them from incoming attacks.", "continuity": "Manga and Anime", "image_url": "/abilities/experimental-ectoplasm.png"},
    {"id": 127, "name": "Fighting Wolf Fist", "category": "Martial Art", "users": [["Free"]], "description": "An aggressive martial art practiced by Free that takes advantage of his immortality, allowing him to endure powerful attacks while maintaining relentless close-range offense. The style uses fluid movement, rapid punches and kicks, and a distinctive hand position resembling sharpened werewolf claws.", "continuity": "Manga and Anime", "image_url": "/abilities/fighting-wolf-fist.png"},
    {"id": 128, "name": "Flight", "category": "Support Ability", "users": [["Lord Death"], ["Mabaa"], ["Asura"], ["Hellworm"], ["Black☆Star"], ["Sky Whale"], ["Ponera"], ["White Rabbit"], ["Jester Clown"]], "description": "An ability that allows the user to fly and move freely through the air without external assistance. It can be naturally possessed, acquired through magic, or developed after prolonged exposure to low-gravity environments such as the Moon.", "continuity": "Manga and Anime", "image_url": "/abilities/flight.png"},
    {"id": 129, "name": "Guilty or Not Guilty", "category": "Weapon Ability", "users": [["Justin Law", "Clown"]], "description": "A Weapon Ability performed by Justin Law while in Madness Fusion with a Clown. By merging both guillotine blades into a single massive weapon, Justin launches it toward the ground with tremendous force, causing it to ricochet unpredictably and strike opponents from unexpected angles.", "continuity": "Manga", "image_url": "/abilities/guilty-or-not-guilty.png"},
    {"id": 130, "name": "Gun Fu", "category": "Martial Art", "users": [["Death the Kid"], ["Sid Barrett"]], "description": "A close-range fighting style that combines gunplay with hand-to-hand combat. Practitioners use firearms at close quarters for rapid shots, strikes, blocks, and weapon-assisted attacks.", "continuity": "Anime", "image_url": "/abilities/gun-fu.png"},
    {"id": 131, "name": "Headbutt of Love", "category": "Martial Art", "users": [["Justin Law"]], "description": "A close-range melee technique used by Justin Law after restraining an opponent with Carcan Bras. Once the target is pulled within range, Justin delivers a powerful headbutt to inflict additional damage.", "continuity": "Manga and Anime", "image_url": "/abilities/headbutt-of-love.png"},
    {"id": 132, "name": "Hero the Atomic", "category": "Soul Resonance", "users": [["Hero", "Excalibur"]], "description": "A Soul Resonance technique performed by Hero and Excalibur in which Hero calls out the attack's name, unleashing a massive holy explosion capable of overwhelming multiple powerful opponents at once. The exact mechanism behind the technique is unknown.", "continuity": "Manga", "image_url": "/abilities/hero-the-atomic.png"},
    {"id": 133, "name": "Holy Cross Chop", "category": "Weapon Ability", "users": [["Justin Law"]], "description": "A Weapon Ability in which Justin Law partially transforms his arms into guillotine blades before executing a horizontal slash followed by a vertical strike, creating a lethal cross-shaped cutting attack.", "continuity": "Manga and Anime", "image_url": "/abilities/holy-cross-chop.png"},
    {"id": 134, "name": "Infinite One-Sword Style", "category": "Martial Art", "users": [["Mifune"]], "description": "Mifune's personal sword style that emphasizes adaptability in both close-range and long-range combat. Rather than relying on fixed forms, the style incorporates a wide variety of unique techniques, allowing the user to respond fluidly to different opponents and situations.", "continuity": "Manga and Anime", "image_url": "/abilities/infinite-one-sword-style.png"},
    {"id": 135, "name": "Instantaneous Maximum Firepower", "category": "Martial Art", "users": [["Kirikou Rung"]], "description": "A fighting style developed by Kirikou Rung that focuses on delivering attacks with the maximum possible force in an instant. The style emphasizes overwhelming offensive power through explosive strikes, though it is ineffective against opponents protected by Black Blood.", "continuity": "Manga", "image_url": "/abilities/maximum-firepower.png"},
    {"id": 136, "name": "Jumbled Lineup", "category": "Weapon Ability", "users": [["Mifune"]], "description": "A technique of the Infinite One-Sword Style in which Mifune spins around a fixed point, swinging his sword in a circular motion to propel nearby blades outward. By controlling the surrounding swords, he creates a rotating defensive barrier while launching relentless attacks from multiple directions.", "continuity": "Manga", "image_url": "/abilities/jumbled-lineup.png"},
    {"id": 137, "name": "Katsu", "category": "Reaper Power", "users": [["Lord Death"]], "description": "A Reaper technique in which the user releases a powerful burst of spiritual energy through a forceful shout, creating a shockwave capable of repelling or dispelling its target. The attack can also be charged and used in combination with other Reaper techniques.", "continuity": "Manga and Anime", "image_url": "/abilities/katsu.png"},
    {"id": 138, "name": "Laser", "category": "Soul Ability", "users": [["Gigant"], ["Asura"], ["Hellworm"], ["Moonlight"]], "description": "A supernatural ability that allows the user to generate and fire concentrated beams of laser energy capable of inflicting devastating damage. The power may be produced naturally or channeled through specialized weapons or items.", "continuity": "Manga and Anime", "image_url": "/abilities/laser.png"},
    {"id": 139, "name": "Letter \"U\" Hunt", "category": "Soul Resonance", "users": [["Maka Albarn", "Soul Eater Evans"]], "description": "A Witch-Hunt Soul Resonance technique performed by Maka Albarn and Soul Eater Evans. During the attack, the pair swing the Demon Scythe upward in a curved arc resembling the letter 'U', delivering a powerful anti-witch slash.", "continuity": "Manga and Anime", "image_url": "/abilities/letter-u-hunt.png"},
    {"id": 140, "name": "Lie Detecting", "category": "Sensory Ability", "users": [["Joe Buttataki"], ["Franken Stein"]], "description": "A sensory technique that allows the user to detect when a person is lying by perceiving subtle disturbances in their soul wavelength through close physical contact. By reading these minute fluctuations, the user can determine whether a statement is truthful.", "continuity": "Manga", "image_url": "/abilities/lie-detecting.png"},
    {"id": 141, "name": "Lightning Flash", "category": "Soul Resonance", "users": [["Kirikou Rung", "Thunder"]], "description": "A Soul Resonance technique performed by Kirikou Rung and Thunder in which Thunder launches a powerful vertical lightning strike from the air, simultaneously cleaving and electrocuting the target.", "continuity": "Manga and Anime", "image_url": "/abilities/lightning-flash.png"},
    {"id": 142, "name": "Living End", "category": "Weapon Ability", "users": [["Sid Barrett", "Gravestone"]], "description": "A close-range Weapon Ability performed by Sid Barrett and Gravestone in which the user leaps toward the target before driving Gravestone's base into the opponent with tremendous force. The impact creates a towering cross-shaped burst of energy and is powerful enough to leave a massive crater if it strikes the ground.", "continuity": "Manga and Anime", "image_url": "/abilities/living-end.png"},
    {"id": 143, "name": "Madness Attack", "category": "Soul Ability", "users": [["Black Clown"], ["Justin Law"], ["Arachne Gorgon"]], "description": "A technique that attacks a target using the user's Madness wavelength. Depending on the user's form of Madness, the attack can induce illusions, assault the target's mind, or gradually pull them into Madness through direct mental interference.", "continuity": "Manga", "image_url": "/abilities/madness-attack.png"},
    {"id": 144, "name": "Magnified Infection", "category": "Soul Ability", "users": [["Clowns"]], "description": "An advanced form of Infection that uses a Clown's Madness to engulf and immobilize its target. Numerous appendages extend from the Clown's body to surround the victim, forming a sealed sphere that traps them physically and mentally before crushing them with overwhelming pressure.", "continuity": "Manga", "image_url": "/abilities/magnified-infection.png"},
    {"id": 145, "name": "Mind Control", "category": "Support Ability", "users": [["Shaula Gorgon"]], "description": "A supernatural ability that allows the user to manipulate or control another individual's mind and bend their will. Shaula Gorgon accomplishes this through a combination of poison and magic, though the effect can be resisted through strong willpower or counteracted with appropriate antidotes.", "continuity": "Manga", "image_url": "/abilities/mind-control.png"},
    {"id": 146, "name": "Multiplication Mode", "category": "Weapon Ability", "users": [["Mifune"]], "description": "A Weapon Ability of the Infinite One-Sword Style that follows Addition Mode. Mifune rapidly strikes the surrounding embedded swords in succession, causing them to slash the opponent a second time before scattering into a circular formation around the target, effectively doubling the damage inflicted.", "continuity": "Manga and Anime", "image_url": "/abilities/multiplication-mode.png"},
    {"id": 147, "name": "Nightmare Noise", "category": "Soul Ability", "users": [["Mosquito"]], "description": "A Soul Ability used by Mosquito in his 400 Years Ago form in which he launches numerous compressed bats capable of cutting and tearing apart opponents from multiple directions or striking them in a concentrated linear barrage.", "continuity": "Manga", "image_url": "/abilities/nightmare-noise.png"},
    {"id": 148, "name": "Number 6 Hunt", "category": "Soul Resonance", "users": [["Maka Albarn", "Soul Eater Evans"]], "description": "A variation of Witch-Hunt performed by Maka Albarn and Soul Eater Evans in which the Demon Scythe is swung in a rotating slash that traces the shape of the number six, delivering a powerful anti-witch attack.", "continuity": "Manga and Anime", "image_url": "/abilities/number-6-hunt.png"},
    {"id": 149, "name": "On Your Mark...Ura!", "category": "Weapon Ability", "users": [["Tsar Pushka"]], "description": "A powerful cannon-based technique in which Tsar Pushka anchors himself to the ground, charges a large amount of energy, and launches his transformed head at the target like a destructive cannonball. After impact, the head retracts through the cord forming his neck, and the technique can be strengthened with his Demon-Repelling Wavelength.", "continuity": "Manga", "image_url": "/abilities/on-your-mark.png"},
    {"id": 150, "name": "Police Stinger", "category": "Soul Ability", "users": [["Mosquito"]], "description": "A Soul Ability in which Mosquito lunges at an opponent using his Stinger to deliver a rapid piercing attack. In the anime, the technique can also be performed while spinning through the air like a rotor before diving into the target.", "continuity": "Manga and Anime", "image_url": "/abilities/police-stinger.png"},
    {"id": 151, "name": "Pressure", "category": "Soul Ability", "users": [["Asura"]], "description": "A Soul Ability in which Asura compresses and projects his Madness of Fear to generate overwhelming pressure. The technique can repel or immobilize opponents, create powerful shockwaves, and mark targets with the Kishin's eye symbol to inflict crushing force capable of incapacitating even powerful enemies.", "continuity": "Manga and Anime", "image_url": "/abilities/pressure.png"},
    {"id": 152, "name": "Puppet Shadow", "category": "Soul Ability", "users": [["Masamune Nakatsukasa"]], "description": "A shadow-manipulation ability that allows Masamune Nakatsukasa to personify his shadow into one or more humanoid Shadow Puppets. These puppets can attack, restrain, grapple, and transform into other shadow-based techniques, serving as the foundation of Masamune's shadow combat style.", "continuity": "Manga and Anime", "image_url": "/abilities/puppet-shadow.png"},
    {"id": 153, "name": "Puppet Strike", "category": "Soul Ability", "users": [["Masamune Nakatsukasa"]], "description": "A Soul Ability derived from Puppet Shadow in which Masamune wraps a Shadow Puppet around the blade of his weapon form, creating a long, hardened shadow extension capable of delivering powerful thrusting attacks from several meters away.", "continuity": "Manga and Anime", "image_url": "/abilities/puppet-strike.png"},
    {"id": 154, "name": "Purification", "category": "Soul Resonance", "users": [["Feodor", "Tsar Pushka"]], "description": "A Soul Resonance technique performed by Feodor and Tsar Pushka that combines Feodor's physical prowess and Anti-Demon Wavelength with Tsar Pushka's Demon Cannon form to purify and eliminate malicious forces such as Black Blood.", "continuity": "Manga", "image_url": "/abilities/purification.png"},
    {"id": 155, "name": "Rainbow", "category": "Soul Resonance", "users": [["Alexandre", "Dengu Dinga"]], "description": "A close-range Soul Resonance technique performed by Alexandre and Dengu Dinga using the Rainbow Axe transformation. Alexandre delivers a powerful overhead swing that produces a wide, rainbow-shaped trail of light, allowing the normally blunt axe to cut through the target across a much larger area.", "continuity": "Manga", "image_url": "/abilities/rainbow.png"},
    {"id": 156, "name": "Real Black Dragon", "category": "Soul Resonance", "users": [["Crona", "Ragnarok"]], "description": "A Soul Resonance transformation achieved by Crona and Ragnarok after Ragnarok absorbs a large number of human souls. The resonance transforms Ragnarok into a massive black dragon extending from Crona's back, greatly enhancing their physical abilities, granting flight, and empowering techniques such as Screech Alpha.", "continuity": "Manga and Anime", "image_url": "/abilities/real-black-dragon.png"},
    {"id": 157, "name": "Reverse Gear", "category": "Soul Ability", "users": [["Giriko"]], "description": "A Soul Ability in which Giriko reverses the direction of his chain's movement after launching an attack. By changing the flow of the chain mid-motion, he can abruptly alter his trajectory or the attack's path to catch opponents off guard.", "continuity": "Manga", "image_url": "/abilities/reverse-gear.png"},
    {"id": 158, "name": "Rose Thorns Storm", "category": "Black Blood", "users": [["Crona", "Ragnarok", "The Black Clown"]], "description": "A large-scale Black Blood technique in which Crona manifests numerous thorn-covered vine-like tentacles that rise into the air and bloom into massive black roses. The flowers then release a powerful shockwave before the thorned tendrils crash down across a wide area, crushing and poisoning anything they strike.", "continuity": "Manga", "image_url": "/abilities/rose-thorns-storm.png"},
    {"id": 159, "name": "Schmidt", "category": "Weapon Ability", "users": [["Justin Law"]], "description": "A Weapon Ability performed while Justin Law is in his Madness Fusion form. Justin drives his transformed forearms into the ground, causing numerous angular stakes to erupt beneath the battlefield before guillotine-like blades rapidly descend between them, creating a devastating area-of-effect attack.", "continuity": "Manga", "image_url": "/abilities/schmidt.png"},
    {"id": 160, "name": "Scythe Weasel", "category": "Soul Resonance", "users": [["Maka Albarn", "Soul Eater Evans"]], "description": "A Soul Resonance technique derived from Witch-Hunt in which the user whips the Soul Wavelengths gathered within the scythe blade back toward their source. The reflected attack is powerful but difficult to control, making it dangerous to both enemies and allies.", "continuity": "Manga", "image_url": "/abilities/scythe-weasel.png"},
    {"id": 161, "name": "Shadow☆Star Zeroth Form: Masamune Initiation Technique - Infinity", "category": "Soul Resonance", "users": [["Black☆Star", "Tsubaki Nakatsukasa"]], "description": "A Soul Resonance technique performed while using Shadow☆Star Zeroth Form: Masamune. While under the influence of madness, Black☆Star generates and controls numerous hardened shadow swords empowered by the Uncanny Sword, launching them in rapid succession to overwhelm opponents.", "continuity": "Manga", "image_url": "/abilities/shadow-star-zero-form-infinity.png"},
    {"id": 162, "name": "Shadow☆Star: Pull and Slash", "category": "Soul Resonance", "users": [["Black☆Star", "Tsubaki Nakatsukasa"]], "description": "A Soul Resonance technique in which Black☆Star summons shadows while Tsubaki remains in her Uncanny Sword form. The shadows capture and restrain the target before pulling them into the path of the blade, allowing Black☆Star to deliver a decisive slash.", "continuity": "Manga and Anime", "image_url": "/abilities/shadow-star-pull-slash.png"},
    {"id": 163, "name": "Shapeshifting", "category": "Support Ability", "users": [["Death"], ["Spirit Albarn"], ["Soul Eater Evans"], ["Little Ogre"]], "description": "An ability that allows the user to alter the shape or size of parts of their body. Commonly demonstrated by Death Weapons and other supernatural beings, it serves as a fundamental transformation ability used for combat, mobility, and utility.", "continuity": "Manga and Anime", "image_url": "/abilities/shapeshifting.png"},
    {"id": 164, "name": "Shield", "category": "Defense Ability", "users": [["Death"], ["Asura"], ["Gigant"]], "description": "A defensive technique that generates a barrier of energy capable of protecting the user from incoming attacks. The shield can originate from various supernatural powers, though sufficiently powerful attacks are capable of breaking through it.", "continuity": "Anime", "image_url": "/abilities/shield.png"},
    {"id": 165, "name": "Shockwave", "category": "Support Ability", "users": [["Nals Garner"], ["Asura"]], "description": "A technique that allows the user to generate and project powerful shockwaves through a simple arm movement. Depending on the user, the shockwave may possess additional properties, such as electrical energy or supernatural power.", "continuity": "Manga and Anime", "image_url": "/abilities/shockwave.png"},
    {"id": 166, "name": "Split Branches", "category": "Weapon Ability", "users": [["Masamune Nakatsukasa", "Ryūku (Possessed)"]], "description": "A follow-up technique performed after Puppet Thrust in which numerous shadow spikes erupt from the extended blade to skewer opponents from multiple directions. The attack strikes with little warning, increasing its effectiveness at close range and making it difficult to evade.", "continuity": "Manga and Anime", "image_url": "/abilities/split-branches.png"},
    {"id": 167, "name": "Stinger", "category": "Weapon Ability", "users": [["Mosquito"]], "description": "Mosquito's extendable, spear-like nose that functions as both a natural weapon and a bloodsucking organ. The Stinger can rapidly extend and retract, pierce opponents with great force, and serves as the foundation for several offensive techniques.", "continuity": "Manga and Anime", "image_url": "/abilities/stinger.png"},
    {"id": 168, "name": "Abashiri: Frigid Jailhouse", "category": "Magic", "users": [["Free"]], "description": "An Ice Magic spell in which Free gathers moisture from the surrounding environment before freezing it into a massive prison of ice around the target. The technique completely immobilizes the victim inside a jail-like structure and can restrain even exceptionally powerful opponents.", "continuity": "Manga", "image_url": "/abilities/abashiri-frigid-jailhouse.png"},
    {"id": 169, "name": "Analyze Decompose", "category": "Magic", "users": [["Medusa Gorgon"]], "description": "A Vector Magic spell in which Medusa summons numerous Vector Arrows and drives them into a single point to tear apart an opponent's magical defenses or protective coatings. The spell is commonly used to dismantle barriers before following up with more destructive attacks.", "continuity": "Manga", "image_url": "/abilities/analyze-decompose.png"},
    {"id": 170, "name": "Angel's Raiment", "category": "Magic", "users": [["Kaguya"]], "description": "A defensive Wardrobe Change spell that equips Kaguya with the Angel's Raiment, a protective outfit capable of withstanding powerful attacks. While wearing it, she can also generate the Heavenly Raiment Wall to create a large defensive barrier around herself or a wide area.", "continuity": "Manga", "image_url": "/abilities/angel-raiment.png"},
    {"id": 171, "name": "Beam Whiskers", "category": "Magic", "users": [["Mizune Family"]], "description": "A magic technique used by the Mizune Family that fires multiple highly concentrated laser beams from whisker-like points on the user's face. The beams can be generated almost instantly and possess enough cutting power to slice through steel and other durable materials with ease.", "continuity": "Manga and Anime", "image_url": "/abilities/beam-whiskers.png"},
    {"id": 172, "name": "Black Wings", "category": "Magic", "users": [["Gopher"]], "description": "A magic technique that allows Gopher to manifest large black wings by drawing upon the magical power of his Grigori soul. The wings grant high-speed flight and can harden their feathers into projectiles, serving as the foundation for techniques such as Bullet Wings.", "continuity": "Manga", "image_url": "/abilities/black-wings.png"},
    {"id": 173, "name": "Bullet Wings", "category": "Magic", "users": [["Gopher"]], "description": "An offensive spell performed through Black Wings in which Gopher fires numerous hardened feather-like projectiles from his Grigori wings in rapid succession. The feathers are quickly regenerated as they are launched, allowing for a continuous barrage capable of piercing opponents over a wide area.", "continuity": "Manga", "image_url": "/abilities/bullet-wings.png"},
    {"id": 174, "name": "Compress Vectors", "category": "Magic", "users": [["Medusa Gorgon"]], "description": "A Vector Magic spell in which Medusa surrounds a target with Vector Arrows before compressing them into a much smaller size. The technique can drastically reduce the size of physical targets, but is ineffective against non-physical entities or those protected by Madness.", "continuity": "Manga", "image_url": "/abilities/compress-vectors.png"},
    {"id": 175, "name": "Demon Eye Cannon", "category": "Magic", "users": [["Free"], ["Mabaa"]], "description": "A powerful magic spell performed through the Demon Eye in which the user manifests a giant eye that gathers a large amount of energy before firing an explosive beam capable of devastating its target. The technique requires considerable magical power and is typically used in the user's stronger form.", "continuity": "Manga", "image_url": "/abilities/demon-eye-cannon.png"},
    {"id": 176, "name": "Flying Pumpkins", "category": "Magic", "users": [["Blair"]], "description": "A utility magic spell that allows Blair to summon large floating pumpkins which she can ride for transportation or command at will. The pumpkins can also bombard opponents by launching explosive projectiles or missiles from the air.", "continuity": "Manga and Anime", "image_url": "/abilities/flying-pumpkins.png"},
    {"id": 177, "name": "Formation", "category": "Magic", "users": [["Mosquito"]], "description": "A sound-based magic technique used by Mosquito in his 400 Years Ago form that allows him to split into a swarm of bats and arrange them into a circular formation around a target. The formation serves as the foundation for powerful follow-up spells such as Darkness Discord.", "continuity": "Manga", "image_url": "/abilities/formation.png"},
    {"id": 178, "name": "Forwarding Protection", "category": "Magic", "users": [["Maba", "Free"]], "description": "An advanced magic spell performed by Maba and Free that combines Soul Protect, Spatial Magic, and Calculation Spells to create a powerful defensive technique capable of protecting against incoming threats through complex magical calculations and spatial manipulation.", "continuity": "Manga", "image_url": "/abilities/forwarding-protection.png"},
    {"id": 179, "name": "Forwarding Vision", "category": "Magic", "users": [["Free"]], "description": "A Spatial Magic spell performed through the Demon Eye that projects a holographic image of the user at another location. The projected image mirrors the user's movements in real time but cannot physically interact with its surroundings, making the technique useful for reconnaissance, deception, and distraction.", "continuity": "Manga and Anime", "image_url": "/abilities/forwarding-vision.png"},
    {"id": 180, "name": "Ice Bind", "category": "Magic", "users": [["Free"]], "description": "An Ice Magic spell that encases a target's feet in ice, immobilizing them and creating an opening for follow-up attacks. Although primarily a restraint technique, the ice is durable enough to temporarily hold even physically powerful opponents.", "continuity": "Manga", "image_url": "/abilities/ice-bind.png"},
    {"id": 181, "name": "Ice Pillar", "category": "Magic", "users": [["Free"]], "description": "An Ice Magic spell that creates a massive pillar of ice at a chosen location by rapidly freezing moisture in the surrounding area. The pillar can be used to strike opponents, obstruct movement, or reshape the battlefield.", "continuity": "Manga and Anime", "image_url": "/abilities/ice-pillar.png"},
    {"id": 182, "name": "Ice Shackle Bullet", "category": "Magic", "users": [["Free"]], "description": "An Ice Magic spell performed after Ice Sphere in which Free strikes the large sphere of ice, launching it at high speed toward the target. The projectile impacts with tremendous force while retaining its freezing properties, allowing it to damage and restrain opponents simultaneously.", "continuity": "Manga and Anime", "image_url": "/abilities/ice-shackle-bullet.png"},
    {"id": 183, "name": "Ice Sphere", "category": "Magic", "users": [["Free"]], "description": "An Ice Magic spell that encases a spherical object in a large mass of dense ice, creating a heavy projectile capable of crushing opponents. The resulting sphere can be used directly as a powerful attack or as the foundation for techniques such as Ice Shackle Bullet.", "continuity": "Manga and Anime", "image_url": "/abilities/ice-sphere.png"},
    {"id": 184, "name": "Icicle Fist", "category": "Magic", "users": [["Free"]], "description": "An Ice Magic spell in which Free encases his entire forearm in a massive block of ice before delivering a powerful uppercut. Unlike Ice Fist, the larger and denser ice construct remains intact after impact, greatly increasing the technique's striking power and allowing it to launch even powerful opponents into the air.", "continuity": "Manga", "image_url": "/abilities/icicle-fist.png"},
    {"id": 185, "name": "Soul Protect: Cancel", "category": "Magic", "users": [["Medusa Gorgon"], ["Eruka Frog"], ["Mizune Family"], ["Free"], ["Maba"], ["Shaula Gorgon"], ["Witch Judge"], ["Tabatha Butterfly"], ["Taruho Firefly"], ["Kimial Diehl"]], "description": "A command used to deactivate Soul Protect, causing the concealment spell to end and allowing the user's magic and soul wavelength to be detected again. The cancellation may be activated verbally or mentally.", "continuity": "Manga and Anime", "image_url": "/abilities/soul-protect-cancel.png"},
    {"id": 186, "name": "Tail Snake", "category": "Magic", "users": [["Medusa Gorgon"]], "description": "A Vector Magic technique that manifests a snake-like Vector Arrow from Medusa's lower back to serve as a tail. It provides balance and mobility, can anchor the user for aerial maneuvers, and may also be used offensively to strike or launch attacks at opponents.", "continuity": "Manga and Anime", "image_url": "/abilities/tail-snake.png"},
    {"id": 187, "name": "Teleport", "category": "Magic", "users": [["Excalibur"], ["Free"], ["Hero", "Excalibur"], ["Lord Death"]], "description": "A teleportation technique that allows the user to instantly travel from one location to another. While the underlying power differs between users, such as Spatial Magic or Reaper Powers, each performs the same instantaneous movement through their own abilities.", "continuity": "Manga", "image_url": "/abilities/teleport.png"},
    {"id": 188, "name": "Vector Arrow x3", "category": "Magic", "users": [["Medusa Gorgon"]], "description": "An enhanced Vector Magic spell that generates three times as many Vector Arrows as the standard Vector Arrow technique. The increased number of vectors creates a more powerful attack capable of restraining multiple targets, though opponents may evade it by escaping through the center of the formation.", "continuity": "Manga and Anime", "image_url": "/abilities/vector-arrow-3.png"},
    {"id": 189, "name": "Vector Blade", "category": "Magic", "users": [["Medusa Gorgon"]], "description": "An anime-exclusive Vector Magic spell that shapes multiple vectors into a massive blade capable of slicing through targets. Medusa can also channel her Soul Wavelength through the blade to launch a ranged slash, though it is less powerful than Soul Menace.", "continuity": "Anime", "image_url": "/abilities/vector-blade.png"},
    {"id": 190, "name": "Vector Boost", "category": "Magic", "users": [["Medusa Gorgon"], ["Kirikou Rung"]], "description": "A support spell that places a vector-shaped mark on a chosen target, doubling the power of attacks performed in the direction indicated by the mark. Medusa commonly uses the spell to enhance the offensive capabilities of her allies.", "continuity": "Manga", "image_url": "/abilities/vector-boost.png"},
    {"id": 191, "name": "Vector Conduct", "category": "Magic", "users": [["Medusa Gorgon"]], "description": "A support spell that allows Medusa to guide a chosen individual by revealing invisible vector markers previously placed along a route. After activating the spell, the target can perceive the hidden arrows, which direct them toward a predetermined destination.", "continuity": "Manga", "image_url": "/abilities/vector-conduct.png"},
    {"id": 192, "name": "Wardrobe Change", "category": "Magic", "users": [["Kaguya"], ["Blair"]], "description": "A transformation spell that allows the user to magically change their clothing or equip specialized outfits. Certain forms provide unique powers and techniques, such as Kaguya's Angel's Raiment and Pelt of the Fire Rat.", "continuity": "Manga and Anime", "image_url": "/abilities/pelt-fire-rat.png"},
    {"id": 193, "name": "Wings of Light", "category": "Magic", "users": [["Excalibur"], ["Hero"], ["Liz Thompson"]], "description": "A supplementary ability granted through Excalibur that manifests radiant golden wings, allowing the wielder to fly at tremendous speed. The wings also enable rapid aerial maneuverability and leave trails of glowing feathers while in flight.", "continuity": "Manga and Anime", "image_url": "/abilities/wings-of-light.png"},
    {"id": 194, "name": "Magic of Eternity", "category": "Magic", "users": [["Sofia Ressa Valk"]], "description": "A powerful resurrection spell that revives a deceased individual by creating a potion from bones and sacrificing three meister and weapon pairs with unyielding spirits. The ritual restores the dead at the cost of tremendous magical and spiritual sacrifice.", "continuity": "Special Social Studies Field Trip", "image_url": "/abilities/magic-of-eternity.png"},
    {"id": 195, "name": "Manipulation Magic", "category": "Magic", "users": [["Shaula Gorgon"]], "description": "A type of magic that allows the user to seize control of another individual's mind and actions through techniques such as poison and other methods of mental manipulation. The caster must remain within a certain range to maintain control over the target.", "continuity": "Soul Eater NOT!", "image_url": "/abilities/manipulation-magic.png"},
    {"id": 196, "name": "Regeneration Magic", "category": "Magic", "users": [["Tanuki Witches"], ["Kimial Diehl"]], "description": "A healing magic that restores injuries, illnesses, and poisons while also repairing damaged objects. Although highly effective at regeneration, it cannot heal scars if the injured person refuses to be healed.", "continuity": "Manga", "image_url": "/abilities/regeneration-magic.png"},
    {"id": 197, "name": "Summon", "category": "Magic", "users": [["Inca Kasugatani"], ["Noah (Greed)"], ["Noah (Wrath)"], ["Eibon"]], "description": "A magic technique that allows the user to summon and materialize other entities, including demons, magical creatures, or constructs. Summoning may be performed directly through magic or by using magical artifacts such as Demon Books.", "continuity": "Manga and Game", "image_url": "/abilities/summon.png"},
]

organizations = [
  {"id": 1, "name": "Death Weapon Meister Academy", "organization_type": "Educational Institution and International Defense Organization", "display_type": "Academy", "leader": "Lord Death", "location": "Death City, Nevada, United States", "members": ["Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Death the Kid", "Liz Thompson", "Patty Thompson", "Franken Stein", "Spirit Albarn", "Marie Mjolnir", "Sid Barrett"], "description": "The Death Weapon Meister Academy, commonly known as the DWMA, is an international organization founded by Lord Death to train meisters and demon weapons. It works to preserve world order, prevent the creation of new Kishin, defeat supernatural threats, and produce Death Scythes capable of serving Lord Death.", "status": "Active", "image_url": "/organizations/organizations-dwma.png"},  
  {"id": 2, "name": "Spartoi", "organization_type": "Elite DWMA Student Unit", "display_type": "Elite Unit", "leader": "DWMA Faculty and Staff", "location": "Death City, Nevada, United States", "members": ["Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Death the Kid", "Liz Thompson", "Patty Thompson", "Kilik Rung", "Pot of Fire", "Pot of Thunder", "Ox Ford", "Harvar D. Eclair", "Kim Diehl", "Jacqueline O. Lantern Dupré"], "description": "Spartoi is an elite DWMA student unit formed after the defeat of Arachnophobia to respond to increasingly dangerous supernatural threats. Its members are selected from the academy's strongest meister and demon weapon teams and are identified by their white uniforms.", "status": "Active", "image_url": "/organizations/organizations-spartoi.png"},  
  {"id": 3, "name": "Arachnophobia", "organization_type": "Witch-Led Military Organization", "display_type": "Witch Faction", "leader": "Arachne Gorgon", "location": "Baba Yaga Castle", "members": ["Arachne Gorgon", "Giriko", "Mosquito", "Mifune"], "description": "Arachnophobia is a large organization founded and led by the witch Arachne Gorgon. After remaining hidden for 800 years, it re-emerges as a major enemy of the DWMA, using Demon Tools, military forces, surveillance networks, and research into madness to expand its power and challenge Lord Death's control.", "status": "Destroyed", "image_url": "/organizations/organizations-arachnophobia.png"},
  {"id": 4, "name": "Medusa's Faction", "organization_type": "Rogue Organization", "display_type": "Rogue Faction", "leader": "Medusa Gorgon", "location": "Underground Laboratories", "members": ["Medusa Gorgon", "Crona", "Ragnarok", "Free", "Eruka Frog"], "description": "A secret organization led by the witch Medusa Gorgon. The group carries out human experimentation, develops Black Blood, and manipulates others from the shadows in an effort to awaken the Kishin Asura and spread madness throughout the world.", "status": "Dissolved", "image_url": "/organizations/medusas-faction.png"},  
  {"id": 5, "name": "Noah's Gang", "organization_type": "Independent Organization", "display_type": "Independent Faction", "leader": "Noah", "location": "Book of Eibon", "members": ["Noah", "Gopher", "Justin Law"], "description": "A small organization led by Noah that operates from within the Book of Eibon. Noah seeks to collect powerful people, objects, and knowledge from across the world, bringing the group into conflict with both the DWMA and other factions.", "status": "Defeated", "image_url": "/organizations/organizations-noahs-group.png"},
  {"id": 6, "name": "Witches' Mass", "organization_type": "Witches' Governing Council", "display_type": "Witch Council", "leader": "Grand Witch Maba", "location": "Witches' Realm", "members": ["Grand Witch Maba"], "description": "The Witches' Mass is the governing council of witches responsible for overseeing magical affairs and representing the interests of witch society. Although the DWMA and witches were long-standing enemies, the organization eventually agrees to cooperate with the academy against greater threats.", "status": "Active", "image_url": "/organizations/organizations-witches-mass.png"},
]

arcs = [
  {"id": 1, "name": "Prologues Arc", "episodes": "1-3", "manga_chapters": "0.1-0.3", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Death the Kid", "Liz Thompson", "Patty Thompson"], "main_conflict": "Collecting 99 evil human souls and one witch soul to create a Death Scythe.", "description": "The series introduces the three meister and weapon teams as they each attempt to collect 99 evil human souls and one witch soul. Despite overcoming powerful opponents, every team fails to complete their final objective, forcing them to start over from the beginning.", "status": "Completed", "image_url": "/arcs/arcs-prologues.png"},
  {"id": 2, "name": "Remedial Lessons Arc", "episodes": "4-6", "manga_chapters": "1-3", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Franken Stein", "Sid Barrett"], "main_conflict": "Completing a dangerous remedial assignment under the supervision of Dr. Franken Stein.", "description": "After failing to collect a witch soul, Maka and Black Star are assigned a remedial mission by Lord Death. Their task leads them to the resurrected Sid Barrett and eventually Dr. Franken Stein, where they must overcome a demanding trial to prove they are worthy students of the DWMA.", "status": "Completed", "image_url": "/arcs/arcs-remedial-lessons.png"},  
  {"id": 3, "name": "Demon Sword Arc", "episodes": "7-9", "manga_chapters": "4-6", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Crona", "Ragnarok", "Franken Stein", "Spirit Albarn", "Medusa Gorgon"], "main_conflict": "Stopping Crona and the Demon Sword Ragnarok before they spread the madness of Black Blood.", "description": "Maka and Soul encounter Crona and the Demon Sword Ragnarok during a mission in Italy. After suffering a crushing defeat, they recover with the help of Dr. Franken Stein and Spirit Albarn before confronting Crona again. The battle also reveals Medusa Gorgon, whose secret experiments begin driving the series' central conflict.", "status": "Completed", "image_url": "/arcs/arcs-demon-sword.png"},
  {"id": 4, "name": "Uncanny Sword Arc", "episodes": "10-12", "manga_chapters": "7-9", "main_characters": ["Black Star", "Tsubaki Nakatsukasa", "Masamune Nakatsukasa", "Mifune", "Angela Leon", "Medusa Gorgon", "Eruka Frog"], "main_conflict": "Stopping the Uncanny Sword Masamune and helping Tsubaki overcome her brother's corruption.", "description": "Black Star and Tsubaki travel to a remote village to stop Masamune, the infamous Uncanny Sword who is revealed to be Tsubaki's older brother. While Black Star battles the master swordsman Mifune to protect Angela Leon, Tsubaki confronts Masamune within his spiritual world and ultimately defeats him, gaining a new weapon technique.", "status": "Completed", "image_url": "/arcs/arcs-uncanny-sword.png"},
  {"id": 5, "name": "Experiment Arc", "episodes": "13-14", "manga_chapters": "10-12", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Free", "Medusa Gorgon"], "main_conflict": "Stopping the immortal criminal Free while uncovering Medusa's growing influence.", "description": "As Maka and Soul continue strengthening their Soul Resonance, Black Star and Tsubaki encounter Free, the legendary immortal werewolf recently manipulated by Medusa Gorgon. During the battle, the students discover new abilities while Medusa's plans continue to unfold behind the scenes.", "status": "Completed", "image_url": "/arcs/arcs-experiment.png"},
  {"id": 6, "name": "Black Dragon Arc", "episodes": "15-16", "manga_chapters": "13-15", "main_characters": ["Death the Kid", "Liz Thompson", "Patty Thompson", "Maka Albarn", "Soul Eater Evans", "Franken Stein", "Medusa Gorgon", "Mizune"], "main_conflict": "Investigating the disappearance of a magical artifact while uncovering Medusa's growing plans.", "description": "Death the Kid, Liz, and Patty investigate the disappearance of a magical artifact aboard the Flying Dutchman while Maka and Soul continue recovering from their encounter with Crona. At the same time, Dr. Franken Stein begins investigating Medusa Gorgon, discovering evidence that connects her to the Black Blood experiments and the looming threat of the Kishin.", "status": "Completed", "image_url": "/arcs/arcs-black-dragon.png"},
  {"id": 7, "name": "A Fight to the Death at the Big Bash Arc", "episodes": "18-24", "manga_chapters": "16-23", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Death the Kid", "Liz Thompson", "Patty Thompson", "Lord Death", "Franken Stein", "Spirit Albarn", "Medusa Gorgon", "Asura"], "main_conflict": "Preventing Medusa from reviving the Kishin Asura during the DWMA's anniversary celebration.", "description": "During the DWMA's anniversary celebration, Medusa launches a coordinated attack on the academy to resurrect the Kishin Asura using Black Blood. While the students and faculty battle Medusa's forces throughout the academy, Asura is ultimately revived and escapes, unleashing a powerful madness that changes the world forever.", "status": "Completed", "image_url": "/arcs/arcs-big-bash.png"},
  {"id": 8, "name": "Trial Enrollment Arc", "episodes": "25-27", "manga_chapters": "24-26", "main_characters": ["Crona", "Ragnarok", "Maka Albarn", "Soul Eater Evans", "Lord Death", "Arachne Gorgon", "Mosquito", "Giriko"], "main_conflict": "Determining whether Crona can become an ally while a powerful witch organization begins to emerge.", "description": "Following Medusa's defeat, Lord Death offers Crona and Ragnarok a chance to redeem themselves by enrolling at the DWMA as trial students. At the same time, Arachne Gorgon awakens after centuries of hiding, reuniting with Mosquito and Giriko to rebuild Arachnophobia and begin a new campaign against the academy.", "status": "Completed", "image_url": "/arcs/arcs-trial-enrollment.png"},
  {"id": 9, "name": "Bodyguard Arc", "episodes": "28", "manga_chapters": "27-28", "main_characters": ["Black Star", "Tsubaki Nakatsukasa", "Mifune", "Angela Leon", "Maka Albarn", "Soul Eater Evans", "Arachne Gorgon"], "main_conflict": "Protecting Angela Leon while confronting Mifune and Arachnophobia's growing influence.", "description": "As Maka recovers from her injuries, Black Star and Tsubaki pursue Mifune in an effort to protect Angela Leon from Arachnophobia. Their confrontation reveals more of Mifune's past and loyalty to Angela while exposing Arachnophobia's development of powerful Demon Tools.", "status": "Completed", "image_url": "/arcs/arcs-bodyguard.png"},
  {"id": 10, "name": "Reunion Express Arc", "episodes": "29-32", "manga_chapters": "29-31", "main_characters": ["Death the Kid", "Liz Thompson", "Patty Thompson", "Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Franken Stein", "Medusa Gorgon", "Joe Buttataki", "Eibon"], "main_conflict": "Recovering the Eternal Spring while Medusa secretly advances Arachnophobia's plans.", "description": "As Dr. Franken Stein pushes the students to improve their teamwork and Soul Resonance, Death the Kid is assigned to recover the magical artifact known as the Eternal Spring aboard the Runaway Express. Meanwhile, Medusa Gorgon secretly returns and manipulates Crona, while Kid's mission raises new questions surrounding Eibon and the origins of the Demon Tools.", "status": "Completed", "image_url": "/arcs/arcs-reunion-express.png"},
  {"id": 11, "name": "BREW - The Tempest Arc", "episodes": "33-37", "manga_chapters": "32-37", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Death the Kid", "Liz Thompson", "Patty Thompson", "Mosquito", "Giriko", "Mifune", "Joe Buttataki", "Eibon"], "main_conflict": "Competing with Arachnophobia to obtain the magical artifact BREW before it can be used against the DWMA.", "description": "The DWMA and Arachnophobia race to recover BREW, a powerful Demon Tool created by Eibon, on the lost island of Losti Island. As both sides clash for control of the artifact, Death the Kid uncovers more of Eibon's history while the students strengthen their teamwork in preparation for the battles ahead.", "status": "Completed", "image_url": "/arcs/arcs-brew-tempest.png"},
  {"id": 12, "name": "Internal Investigation Arc", "episodes": "38-40", "manga_chapters": "38-40", "main_characters": ["Franken Stein", "Death the Kid", "Joe Buttataki", "Marie Mjolnir", "Medusa Gorgon", "Crona", "Black Star", "Tsubaki Nakatsukasa", "Maka Albarn", "Soul Eater Evans"], "main_conflict": "Uncovering the source of the DWMA's internal corruption while Medusa secretly manipulates events from within the academy.", "description": "As Dr. Franken Stein begins investigating the growing signs of madness within the DWMA, Death the Kid works alongside Joe Buttataki to uncover the truth behind Eibon's Demon Tools. Meanwhile, Medusa secretly manipulates Crona and the academy from the shadows, pushing Stein closer to madness while deepening the conflict with Arachnophobia.", "status": "Completed", "image_url": "/arcs/arcs-internal-investigation.png"},
  {"id": 13, "name": "Clown Arc", "episodes": None, "manga_chapters": "41-44", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Death the Kid", "Black Star", "Tsubaki Nakatsukasa", "Kim Diehl", "The Clown"], "main_conflict": "Investigating the appearance of the Clown while confronting a growing source of madness beneath Death City.", "description": "Maka and Soul investigate the abandoned Borscht Devlin Factory, where they encounter the Clown, a physical manifestation of madness. At the same time, Death the Kid follows a mysterious tip that reveals Kim Diehl's hidden identity, while the DWMA discovers that madness has begun spreading throughout Death City.", "status": "Completed", "image_url": "/arcs/arcs-clown.png"},
  {"id": 14, "name": "Operation Capture Baba Yaga Castle Arc", "episodes": "41-47", "manga_chapters": "45-60", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Death the Kid", "Liz Thompson", "Patty Thompson", "Crona", "Medusa Gorgon", "Arachne Gorgon", "Mosquito", "Giriko", "Mifune", "Justin Law"], "main_conflict": "Launching a full-scale assault on Baba Yaga Castle to defeat Arachnophobia and stop the creation of the Brew-powered Morality Manipulation Machine.", "description": "The DWMA launches a large-scale assault on Baba Yaga Castle to rescue Brew and eliminate Arachnophobia's headquarters. As the battle unfolds, the students confront powerful enemies, Maka discovers the true nature of Soul's Black Blood, and the conflict ends with the fall of Arachne and the destruction of the castle.", "status": "Completed", "image_url": "/arcs/arcs-capture-baba-yaga-castle.png"},
  {"id": 15, "name": "Kishin Battle Arc", "episodes": "48-51", "manga_chapters": None, "main_characters": ["Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Death the Kid", "Liz Thompson", "Patty Thompson", "Lord Death", "Asura"], "main_conflict": "Defeating the Kishin Asura before his madness consumes the world.", "description": "After the battle at Baba Yaga Castle, Maka and her allies launch a final assault against the Kishin Asura. Working together, the students confront the source of madness itself, bringing the anime's original storyline to a close.", "status": "Completed", "image_url": "/arcs/arcs-kishin-battle.png"},
  {"id": 16, "name": "Grigori Arc", "episodes": None, "manga_chapters": "61-65", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Death the Kid", "Black Star", "Tsubaki Nakatsukasa", "Noah", "Gopher"], "main_conflict": "Protecting Maka from Noah's forces while Spartoi prepares for a new threat.", "description": "Following the fall of Arachnophobia, the DWMA forms Spartoi, an elite unit tasked with responding to the growing threat posed by Noah and his followers. As Maka awakens her Grigori Soul, Gopher targets her on Noah's orders in an attempt to obtain her soul and locate Asura.", "status": "Completed", "image_url": "/arcs/arcs-grigori.png"},
  {"id": 17, "name": "Witch's Research Arc", "episodes": None, "manga_chapters": "66-67", "main_characters": ["Black Star", "Tsubaki Nakatsukasa", "Azusa Yumi", "Medusa Gorgon", "Crona", "Black Clown"], "main_conflict": "Tracking down Medusa while investigating her latest experiments in Africa.", "description": "Spartoi is dispatched to Africa under the supervision of Azusa Yumi to locate Medusa after her reappearance. During the mission, Black Star and Tsubaki encounter Crona and Medusa's newly created Black Clown, revealing that Medusa's experiments have continued despite her apparent defeat.", "status": "Completed", "image_url": "/arcs/arcs-witch-research.png"},
  {"id": 18, "name": "Business Lunch Arc", "episodes": None, "manga_chapters": "68-71", "main_characters": ["Black Star", "Tsubaki Nakatsukasa", "Crona", "Medusa Gorgon", "Justin Law", "Death the Kid", "Noah", "Gopher", "Lord Death", "Maka Albarn", "Soul Eater Evans"], "main_conflict": "Stopping Medusa and Crona while preparing a plan to rescue Death the Kid from the Book of Eibon.", "description": "Black Star and Tsubaki confront Crona as Medusa battles Justin Law, allowing Crona to escape despite the DWMA's efforts. Meanwhile, Lord Death gathers allies to organize a mission into the Book of Eibon after learning that Death the Kid remains imprisoned by Noah.", "status": "Completed", "image_url": "/arcs/arcs-business-lunch.png"},
  {"id": 19, "name": "Salvage Arc", "episodes": None, "manga_chapters": "72-81", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Death the Kid", "Noah", "Gopher", "Excalibur", "Blair"], "main_conflict": "Rescuing Death the Kid from the Book of Eibon before Noah can use him for his own plans.", "description": "Spartoi enters the Book of Eibon to rescue Death the Kid from Noah and his followers. As they journey through the book's shifting worlds, the group encounters powerful enemies, uncovers more of Noah's ambitions, and moves closer to freeing Kid from captivity.", "status": "Completed", "image_url": "/arcs/arcs-salvage.png"},
  {"id": 20, "name": "Mad Blood Arc", "episodes": None, "manga_chapters": "82-88", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Crona", "Medusa Gorgon", "Death the Kid", "Lord Death", "Noah", "Gopher"], "main_conflict": "Stopping Crona before the Black Blood and madness consume both them and the world.", "description": "As the DWMA continues its pursuit of Asura, Crona falls deeper under the influence of the Black Blood and Medusa's manipulation. The growing madness reshapes the balance of power, forcing the academy to prepare for a final confrontation with both Crona and the Kishin.", "status": "Completed", "image_url": "/arcs/arcs-mad-blood.png"},
  {"id": 21, "name": "Hunt Arc", "episodes": None, "manga_chapters": "89-90", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Death the Kid", "Black Star", "Tsubaki Nakatsukasa", "Lord Death", "Crona", "Tezca Tlipoca"], "main_conflict": "Locating Asura while deciding whether to carry out Death's order to execute Crona.", "description": "After Maka locates Asura on the Moon, Lord Death orders the DWMA to launch its final assault while also issuing an execution order for Crona. Refusing to abandon their friend, Maka, Soul, Black Star, and Tsubaki choose to defy those orders, setting the stage for the final battle.", "status": "Completed", "image_url": "/arcs/arcs-hunt.png"},
  {"id": 22, "name": "War on the Moon Arc", "episodes": None, "manga_chapters": "91-97", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Death the Kid", "Black Star", "Tsubaki Nakatsukasa", "Franken Stein", "Marie Mjolnir", "Lord Death", "Justin Law", "Crona", "Asura"], "main_conflict": "Launching the DWMA's assault on the Moon while racing to stop Crona before they join Asura.", "description": "The DWMA begins its final assault on the Moon, battling Asura's Clown Army while Maka continues searching for Crona in Italy. As the war escalates, Franken Stein and Marie defeat Justin Law, and Lord Death forms an uneasy alliance with the witches to strengthen humanity's chances against the Kishin.", "status": "Completed", "image_url": "/arcs/arcs-war-moon.png"},
  {"id": 23, "name": "Witches' Trial Arc", "episodes": None, "manga_chapters": "98-100", "main_characters": ["Death the Kid", "Maka Albarn", "Soul Eater Evans", "Black Star", "Tsubaki Nakatsukasa", "Lord Death", "Franken Stein", "Marie Mjolnir", "Crona", "Asura"], "main_conflict": "Securing an alliance with the Witch Order while the battle against Asura continues on the Moon.", "description": "Death the Kid enters the Witches' Realm to convince the Witch Order to join forces with the DWMA against Asura. Meanwhile, the war on the Moon intensifies as Maka and Black Star arrive to reinforce their allies, while Crona moves closer to Asura's location.", "status": "Completed", "image_url": "/arcs/arcs-witches-trial.png"},
  {"id": 24, "name": "War on the Moon II Arc", "episodes": None, "manga_chapters": "101-103", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Death the Kid", "Black Star", "Tsubaki Nakatsukasa", "Lord Death", "Asura", "Crona", "Noah", "Maba"], "main_conflict": "Defeating Asura's Clown Army while preparing for the final confrontation with the Kishin.", "description": "The Witch Order joins forces with the DWMA, allowing the allied forces to eliminate Asura's Clown Army and secure the Moon's surface. As the battle reaches its turning point, Asura awakens, Crona closes in on the Kishin, and the stage is set for the final confrontation.", "status": "Completed", "image_url": "/arcs/arcs-war-moon-2.png"},
  {"id": 25, "name": "Dark Side of the Moon Arc", "episodes": None, "manga_chapters": "104-113", "main_characters": ["Maka Albarn", "Soul Eater Evans", "Death the Kid", "Black Star", "Tsubaki Nakatsukasa", "Asura", "Crona", "Lord Death", "Spirit Albarn", "Franken Stein"], "main_conflict": "Defeating the Kishin Asura and ending the spread of madness once and for all.", "description": "The DWMA launches its final battle against Asura after Crona absorbs the Kishin, forcing Maka, Black Star, Death the Kid, and their allies into one last confrontation. As the war reaches its climax, Death the Kid awakens his full powers as a Shinigami, Crona makes a final sacrifice to stop the spread of madness, and the world enters a new era of peace.", "status": "Completed","image_url": "/arcs/arcs-dark-side-moon.png"},
]